window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-556915fcf090bec4"]={"versions": [{"id": "FIG-556915fcf090bec4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses beim Empfang einer I-PDU im AUTOSAR-Basissoftware-Schichtenmodell (Classic Platform). Gezeigt wird die synchrone Weiterleitung einer vom FlexRay Interface (<code>FrIf</code>) empfangenen I-PDU über den PDU Router (<code>PduR</code>) an das Kommunikationsmodul (<code>Com</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module / Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» Com</code>: Oberes Kommunikationsmodul (Empfänger der I-PDU, markiert mit Zerlegungssymbol).\n</li><li><code>«module» PduR</code>: PDU Router zur Weiterleitung ohne Zwischenpufferung.\n</li><li><code>«module» FrIf</code>: FlexRay Interface als untere Kommunikationsschnittstelle.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, PduInfoType*)</code>: Generischer Callback des PDU Routers für untere Schnittstellenmodule (hier instanziiert durch <code>FrIf</code>).\n</li><li><code>Com_RxIndication(PduIdType, PduInfoType*)</code>: Rx-Indikations-Callback des COM-Moduls.\n</li><li>Interne Aktion <code>copy buffer()</code> auf Ebene von <code>Com</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notiz:</strong> Zugeordnet an der Lebenslinie von <code>PduR</code>: „Reception of IPDU going directly to COM. No buffering in PduR is needed“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das FlexRay Interface (<code>FrIf</code>) signalisiert den Empfang einer I-PDU synchron über den Funktionsaufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, PduInfoType*)</code> an den <code>PduR</code>.\n</li><li>Der <code>PduR</code> leitet den Aufruf unmittelbar und ohne Zwischenspeicherung über <code>Com_RxIndication(PduIdType, PduInfoType*)</code> synchron an das Zielmodul <code>Com</code> weiter.\n</li><li>Innerhalb des Ausführungskontexts von <code>Com_RxIndication</code> führt <code>Com</code> eine interne Operation <code>copy buffer()</code> aus, um die empfangenen PDU-Nutzdaten in seinen lokalen Puffer zu kopieren.\n</li><li>Der Funktionsaufruf kehrt synchron via Rückkehrpfeil (gestrichelte Linie) von <code>Com</code> an <code>PduR</code> zurück.\n</li><li>Der Aufruf kehrt anschließend vom <code>PduR</code> synchron via Rückkehrpfeil an <code>FrIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Direkte I-PDU-Weiterleitung von FrIf an COM erfordert im PduR keine Pufferung (Zero-Buffering / Pass-Through-Prinzip).\n</li><li>Gültigkeit der Daten: Da der Datenzeiger (<code>PduInfoType*</code>) übergeben wird und der Aufruf vollständig synchron blockierend abgewickelt wird, muss der Puffer im Empfängerkontext (<code>Com</code>) kopiert werden (<code>copy buffer()</code>), bevor der Aufruf an den Treiber/die Schnittstelle zurückkehrt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d4005355e3005209", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses beim Empfang einer I-PDU im AUTOSAR-Basissoftware-Schichtenmodell (Classic Platform). Gezeigt wird die synchrone Weiterleitung einer vom FlexRay Interface (<code>FrIf</code>) empfangenen I-PDU über den PDU Router (<code>PduR</code>) an das Kommunikationsmodul (<code>Com</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module / Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» Com</code>: Oberes Kommunikationsmodul (Empfänger der I-PDU, markiert mit Zerlegungssymbol).\n</li><li><code>«module» PduR</code>: PDU Router zur Weiterleitung ohne Zwischenpufferung.\n</li><li><code>«module» FrIf</code>: FlexRay Interface als untere Kommunikationsschnittstelle.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code>: Generischer Callback des PDU Routers für untere Schnittstellenmodule mit konstantem Zeiger auf PduInfoType.\n</li><li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Rx-Indikations-Callback des COM-Moduls mit konstantem Zeiger auf PduInfoType.\n</li><li>Interne Aktion <code>copy buffer()</code> auf Ebene von <code>Com</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notiz:</strong> Zugeordnet an der Lebenslinie von <code>PduR</code>: „Reception of IPDU going directly to COM. No buffering in PduR is needed“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das FlexRay Interface (<code>FrIf</code>) signalisiert den Empfang einer I-PDU synchron über den Funktionsaufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code> an den <code>PduR</code>.\n</li><li>Der <code>PduR</code> leitet den Aufruf unmittelbar und ohne Zwischenspeicherung über <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> synchron an das Zielmodul <code>Com</code> weiter.\n</li><li>Innerhalb des Ausführungskontexts von <code>Com_RxIndication</code> führt <code>Com</code> eine interne Operation <code>copy buffer()</code> aus, um die empfangenen PDU-Nutzdaten in seinen lokalen Puffer zu kopieren.\n</li><li>Der Funktionsaufruf kehrt synchron via Rückkehrpfeil (gestrichelte Linie) von <code>Com</code> an <code>PduR</code> zurück.\n</li><li>Der Aufruf kehrt anschließend vom <code>PduR</code> synchron via Rückkehrpfeil an <code>FrIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Direkte I-PDU-Weiterleitung von FrIf an COM erfordert im PduR keine Pufferung (Zero-Buffering / Pass-Through-Prinzip).\n</li><li>Konstanz und Datensicherheit: Durch die Signatur mit <code>const PduInfoType*</code> wird garantiert, dass weder PduR noch Com die empfangenen Pufferinhalte des FrIf modifizieren dürfen.\n</li><li>Gültigkeit der Daten: Da die Datenübergabe über Zeiger erfolgt und synchron abläuft, muss Com die Nutzdaten mittels <code>copy buffer()</code> sichern, bevor der Kontrollfluss an FrIf zurückgegeben wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bcfe64cdfb81c4bd", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses beim Empfang einer I-PDU im AUTOSAR-Basissoftware-Schichtenmodell (Classic Platform). Gezeigt wird die synchrone Weiterleitung einer vom FlexRay Interface (<code>FrIf</code>) empfangenen I-PDU über den PDU Router (<code>PduR</code>) an das Kommunikationsmodul (<code>Com</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module / Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» Com</code>: Oberes Kommunikationsmodul (Empfänger der I-PDU, markiert mit Zerlegungssymbol).\n</li><li><code>«module» PduR</code>: PDU Router zur Weiterleitung ohne Zwischenpufferung.\n</li><li><code>«module» FrIf</code>: FlexRay Interface als untere Kommunikationsschnittstelle.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code>: Generischer Callback des PDU Routers für untere Schnittstellenmodule mit konstantem Zeiger auf PduInfoType.\n</li><li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Rx-Indikations-Callback des COM-Moduls mit konstantem Zeiger auf PduInfoType.\n</li><li>Interne Aktion <code>copy buffer()</code> auf Ebene von <code>Com</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notiz:</strong> Zugeordnet an der Lebenslinie von <code>PduR</code>: „Reception of IPDU going directly to COM. No buffering in PduR is needed“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das FlexRay Interface (<code>FrIf</code>) signalisiert den Empfang einer I-PDU synchron über den Funktionsaufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code> an den <code>PduR</code>.\n</li><li>Der <code>PduR</code> leitet den Aufruf unmittelbar und ohne Zwischenspeicherung über <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> synchron an das Zielmodul <code>Com</code> weiter.\n</li><li>Innerhalb des Ausführungskontexts von <code>Com_RxIndication</code> führt <code>Com</code> eine interne Operation <code>copy buffer()</code> aus, um die empfangenen PDU-Nutzdaten in seinen lokalen Puffer zu kopieren.\n</li><li>Der Funktionsaufruf kehrt synchron via Rückkehrpfeil (gestrichelte Linie) von <code>Com</code> an <code>PduR</code> zurück.\n</li><li>Der Aufruf kehrt anschließend vom <code>PduR</code> synchron via Rückkehrpfeil an <code>FrIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Direkte I-PDU-Weiterleitung von FrIf an COM erfordert im PduR keine Pufferung (Zero-Buffering / Pass-Through-Prinzip).\n</li><li>Konstanz und Datensicherheit: Durch die Signatur mit <code>const PduInfoType*</code> wird garantiert, dass weder PduR noch Com die empfangenen Pufferinhalte des FrIf modifizieren dürfen.\n</li><li>Gültigkeit der Daten: Da die Datenübergabe über Zeiger erfolgt und synchron abläuft, muss Com die Nutzdaten mittels <code>copy buffer()</code> sichern, bevor der Kontrollfluss an FrIf zurückgegeben wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4f5d2d600f88ebd7", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses beim Empfang einer I-PDU im AUTOSAR-Basissoftware-Schichtenmodell (Classic Platform). Gezeigt wird die synchrone Weiterleitung einer vom FlexRay Interface (<code>FrIf</code>) empfangenen I-PDU über den PDU Router (<code>PduR</code>) an das Kommunikationsmodul (<code>Com</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module / Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» Com</code>: Oberes Kommunikationsmodul (Empfänger der I-PDU, markiert mit Zerlegungssymbol).\n</li><li><code>«module» PduR</code>: PDU Router zur Weiterleitung ohne Zwischenpufferung.\n</li><li><code>«module» FrIf</code>: FlexRay Interface als untere Kommunikationsschnittstelle.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code>: Generischer Callback des PDU Routers für untere Schnittstellenmodule mit konstantem Zeiger auf PduInfoType.\n</li><li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Rx-Indikations-Callback des COM-Moduls mit konstantem Zeiger auf PduInfoType.\n</li><li>Interne Aktion <code>copy buffer()</code> auf Ebene von <code>Com</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notiz:</strong> Zugeordnet an der Lebenslinie von <code>PduR</code>: „Reception of IPDU going directly to COM. No buffering in PduR is needed“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das FlexRay Interface (<code>FrIf</code>) signalisiert den Empfang einer I-PDU synchron über den Funktionsaufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code> an den <code>PduR</code>.\n</li><li>Der <code>PduR</code> leitet den Aufruf unmittelbar und ohne Zwischenspeicherung über <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> synchron an das Zielmodul <code>Com</code> weiter.\n</li><li>Innerhalb des Ausführungskontexts von <code>Com_RxIndication</code> führt <code>Com</code> eine interne Operation <code>copy buffer()</code> aus, um die empfangenen PDU-Nutzdaten in seinen lokalen Puffer zu kopieren.\n</li><li>Der Funktionsaufruf kehrt synchron via Rückkehrpfeil (gestrichelte Linie) von <code>Com</code> an <code>PduR</code> zurück.\n</li><li>Der Aufruf kehrt anschließend vom <code>PduR</code> synchron via Rückkehrpfeil an <code>FrIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Direkte I-PDU-Weiterleitung von FrIf an COM erfordert im PduR keine Pufferung (Zero-Buffering / Pass-Through-Prinzip).\n</li><li>Konstanz und Datensicherheit: Durch die Signatur mit <code>const PduInfoType*</code> wird garantiert, dass weder PduR noch Com die empfangenen Pufferinhalte des FrIf modifizieren dürfen.\n</li><li>Gültigkeit der Daten: Da die Datenübergabe über Zeiger erfolgt und synchron abläuft, muss Com die Nutzdaten mittels <code>copy buffer()</code> sichern, bevor der Kontrollfluss an FrIf zurückgegeben wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-556915fcf090bec4", "to": "FIG-d4005355e3005209", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication</code>: Zweiter Parameter von <code>PduInfoType*</code> zu <code>const PduInfoType*</code> geändert.\n</li><li><code>Com_RxIndication</code>: Zweiter Parameter von <code>PduInfoType*</code> zu <code>const PduInfoType*</code> geändert.\n</li></ul>"}, {"from": "FIG-d4005355e3005209", "to": "FIG-bcfe64cdfb81c4bd", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bcfe64cdfb81c4bd", "to": "FIG-4f5d2d600f88ebd7", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
